// Este nodo filtra solo las ventas nuevas comparando con el último ID procesado.
// n8n guarda el estado entre ejecuciones usando getWorkflowStaticData.
const staticData = $getWorkflowStaticData('node');
const lastProcessedId = staticData.lastProcessedId || 0;

// La respuesta de Invok viene en body.result o body directamente
const responseBody = $input.first().json;
const orders = responseBody.result || responseBody;

if (!Array.isArray(orders) || orders.length === 0) {
  return [];
}

// Filtrar solo órdenes con ID mayor al último procesado
const newOrders = orders.filter(order => order.id > lastProcessedId);

if (newOrders.length === 0) {
  return [];
}

// Actualizar el último ID procesado al máximo encontrado
staticData.lastProcessedId = Math.max(...newOrders.map(o => o.id));

// Retornar cada orden nueva como un item separado para que n8n las procese una por una
return newOrders.map(order => ({ json: order }));

